import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = [int(x) for x in data[1:1 + n]]
    INF = float('inf')
    # suffix max / min of a[k] for k > j
    smax = [-INF] * (n + 1)
    smin = [INF] * (n + 1)
    for k in range(n - 1, -1, -1):
        smax[k] = max(smax[k + 1], a[k])
        smin[k] = min(smin[k + 1], a[k])
    best = -INF
    lmax, lmin = a[0], a[0]
    for j in range(1, n - 1):
        rmax, rmin = smax[j + 1], smin[j + 1]
        for x in (lmax - a[j], lmin - a[j]):
            for y in (rmax, rmin):
                if x * y > best:
                    best = x * y
        if a[j] > lmax:
            lmax = a[j]
        if a[j] < lmin:
            lmin = a[j]
    print(best)

